SELECT sku, name, pack, flow
FROM store.products
WHERE lower(name) LIKE '%atta%' AND lower(pack) LIKE '%5 kg%';

SELECT date, units_sold
FROM store.daily_sales
WHERE sku = 'ATTA-WW-5KG' AND date >= DATE '2026-06-01' AND date < DATE '2026-07-01';

SELECT SUM(units_sold) AS total_units
FROM store.daily_sales
WHERE sku = 'ATTA-WW-5KG' AND date >= DATE '2026-06-01' AND date < DATE '2026-07-01';

SELECT COUNT(*) AS empty_audits
FROM store.shelf_audits
WHERE sku = 'ATTA-WW-5KG' AND audit_ts >= TIMESTAMP '2026-06-01 00:00:00' AND audit_ts < TIMESTAMP '2026-07-01 00:00:00' AND status = 'empty';

